CREATE OR REPLACE PACKAGE BODY headcount_report AS

  FUNCTION get_department_headcount(p_dept_id IN NUMBER) RETURN NUMBER IS
    l_count NUMBER;
  BEGIN
    SELECT COUNT(*)
    INTO l_count
    FROM employees
    WHERE department_id = p_dept_id;

    RETURN l_count;
  END get_department_headcount;

END headcount_report;
